import{n as e,r as t,t as n}from"./format-BKtLksMw.js";var r=e=>e*2.23694,i={students:{key:`students`,name:`Students`,theme:`cartoon`,askLabel:`Ask Ace anything!`,askHint:`Point your phone camera here`,chapters:[{id:`hello`,label:`Hello`,action:`hero`,seconds:12,eyebrow:`Hi there!`,title:()=>`I'm Ace, your neighbourhood wind turbine.`,body:()=>`I'm the tallest onshore wind turbine in England — and I belong to the people of Lawrence Weston.`,stat:()=>({value:`208`,unit:`m`,label:`tall to my blade tip — over twice Big Ben!`})},{id:`wind`,label:`Wind`,action:`blades`,seconds:12,eyebrow:`Feel that?`,title:e=>e.windSpeed<2.5?`Not much wind… I'm waiting!`:`The wind is blowing at ${Math.round(r(e.windSpeed))} mph!`,body:e=>`That's a ${e.beaufort.toLowerCase()}. I start spinning at about 6 mph and reach full power at 28 mph.`,stat:e=>({value:Math.round(r(e.windSpeed)),unit:`mph`,label:`wind speed right now`})},{id:`blades`,label:`Blades`,action:`spin_blades`,seconds:12,eyebrow:`Zoom!`,title:e=>e.tipMph>1?`My blade tips are flying at ${t(e.tipMph)} mph!`:`My blades are resting right now.`,body:()=>`Each blade is about 56 m long — longer than two blue whales nose to tail.`,stat:e=>({value:e.rotorRpm.toFixed(1),unit:`rpm`,label:`turns every minute — the same speed as the real me`})},{id:`inside`,label:`Inside`,action:`look_inside`,seconds:16,eyebrow:`Let's peek inside!`,title:()=>`No gearbox — just a giant ring of magnets!`,body:()=>`My blades turn a huge ring of magnets past copper coils. Moving magnets push electricity along the wires.`,stat:()=>({value:`48`,unit:`coils`,label:`of copper in my generator (in this model)`})},{id:`tower`,label:`Tower`,action:`tower_inside`,seconds:14,eyebrow:`Going down!`,title:()=>`Engineers climb up inside me.`,body:()=>`There's a ladder and a tiny lift inside my tower. It's about 150 m to the top — like climbing 50 floors!`,stat:()=>({value:`150`,unit:`m`,label:`to the top of my tower`})},{id:`homes`,label:`Homes`,action:`close_inside`,seconds:13,eyebrow:`Power to the people`,title:e=>e.homes>0?`I'm powering ${t(e.homes)} homes right now!`:`I'm saving up my energy for the next gust.`,body:e=>`Today I've made enough electricity to boil ${t(e.cupsOfTea)} cups of tea. ☕`,stat:e=>({value:t(e.homes),unit:`homes`,label:`lit up by me, right now`})},{id:`ask`,label:`Ask me`,action:`overview`,seconds:12,eyebrow:`Your turn`,title:()=>`Scan the code and ask me anything!`,body:()=>`Ask how fast I spin, what's inside me, or what I do in a storm. You can even make me open up on this screen!`,stat:e=>({value:t(e.phoneCharges),unit:`phones`,label:`charged by my energy today`})}]},community:{key:`community`,name:`Community`,theme:`realistic`,askLabel:`Ask Ace`,askHint:`Scan with your phone camera — no app, no login`,chapters:[{id:`ours`,label:`Ours`,action:`overview`,seconds:13,eyebrow:`Lawrence Weston`,title:()=>`Our turbine. Our power.`,body:()=>`Run by Ambition Community Energy, set up by residents. The income supports Ambition Lawrence Weston's work on fuel poverty and the neighbourhood.`,stat:e=>({value:t(e.homes),unit:`homes`,label:`powered right now`})},{id:`now`,label:`Now`,action:`hero`,seconds:12,eyebrow:`Right now`,title:e=>e.powerKw>0?`Making ${e.power.value} ${e.power.unit} of clean electricity`:`Resting until the wind picks up`,body:e=>`Wind ${e.windSpeed.toFixed(1)} m/s from the ${n(e.windDir)}. The rotor is turning at ${e.rotorRpm.toFixed(1)} rpm.`,stat:e=>({value:e.power.value,unit:e.power.unit,label:`live output`})},{id:`today`,label:`Today`,action:`blades`,seconds:12,eyebrow:`So far today`,title:e=>`${e.today.value} ${e.today.unit} generated today`,body:e=>`That's about ${t(e.co2Kg)} kg of CO₂ kept out of the air — what ${t(e.trees)} trees soak up in a year.`,stat:e=>({value:t(e.co2Kg),unit:`kg CO₂`,label:`avoided today`})},{id:`inside`,label:`Inside`,action:`look_inside`,seconds:16,eyebrow:`Look inside`,title:()=>`What's up there, 150 m above the estate?`,body:()=>`No gearbox. The blades turn a ring generator directly; a converter tidies the power and a transformer sends it into the grid.`,stat:()=>({value:`4.2`,unit:`MW`,label:`maximum output`})},{id:`week`,label:`This week`,action:`close_inside`,seconds:13,eyebrow:`The last 7 days`,title:t=>t.weekKwh>0?`${e(t.weekKwh).value} ${e(t.weekKwh).unit} this week`:`Every kilowatt-hour counts`,body:e=>e.weekKwh>0?`Enough for ${t(e.weekKwh/7/8.4)} homes' daily electricity, every day this week.`:`Weekly figures appear here once the history database has synced.`,stat:e=>({value:e.fundGbp>0?`£${t(e.fundGbp)}`:`—`,unit:``,label:`estimated community income today`})},{id:`lifetime`,label:`Since 2023`,action:`low`,seconds:12,eyebrow:`Since spring 2023`,title:e=>`${e.lifetime.value} ${e.lifetime.unit} of local, clean power`,body:()=>`Every unit generated here is one that didn't have to come from gas.`,stat:e=>({value:e.lifetime.value,unit:e.lifetime.unit,label:`generated in total`})},{id:`ask`,label:`Ask`,action:`hero`,seconds:12,eyebrow:`Got a question?`,title:()=>`Scan to chat with the turbine.`,body:()=>`Your chat stays on your phone — nobody else can see it, and nothing you type appears on this screen.`,stat:e=>({value:t(e.homes),unit:`homes`,label:`powered right now`})}]},college:{key:`college`,name:`College`,theme:`blueprint`,askLabel:`Query Ace`,askHint:`Scan to ask about the data, the physics or the engineering`,chapters:[{id:`spec`,label:`Spec`,action:`overview`,seconds:13,eyebrow:`Enercon E-115 EP3 · WEC EP3-CS02`,title:()=>`4.2 MW gearless, direct-drive.`,body:()=>`Rotor Ø 115.7 m (swept area ≈ 10,500 m²). Hub ≈ 150 m, tip ≈ 208 m. Cut-in 2.5 m/s · rated 12.5 m/s · storm control from 28 m/s.`,stat:()=>({value:`10,514`,unit:`m²`,label:`swept area`}),panel:`spec`},{id:`curve`,label:`Power curve`,action:`blades`,seconds:16,eyebrow:`P ∝ v³ until rated`,title:e=>`Operating at ${e.windSpeed.toFixed(1)} m/s → ${t(e.powerKw)} kW`,body:e=>`Theoretical at this wind: ${t(e.theoreticalKw)} kW. Capacity utilisation now: ${e.utilisation.toFixed(0)}% of 4,245 kW.`,stat:e=>({value:e.utilisation.toFixed(0),unit:`%`,label:`of rated power`}),panel:`curve`},{id:`rotor`,label:`Rotor`,action:`face`,seconds:13,eyebrow:`Tip-speed ratio`,title:e=>`λ = ${e.tsr.toFixed(1)} at ${e.rotorRpm.toFixed(1)} rpm`,body:e=>`Tip speed ${e.tipMs.toFixed(0)} m/s. Variable speed keeps λ near its optimum so the blades extract the most energy.`,stat:e=>({value:e.tipMs.toFixed(0),unit:`m/s`,label:`blade tip speed`})},{id:`generator`,label:`Generator`,action:`look_inside`,seconds:17,eyebrow:`Section cutaway · x-ray · exploded view`,title:()=>`Annular ring generator, no gearbox.`,body:()=>`Hub → rotor → stator coils at rotor speed. Full-power converter decouples generator frequency from the 50 Hz grid; yaw drives on a slewing ring track the wind.`,stat:e=>({value:n(e.nacelleDeg),unit:`${Math.round(e.nacelleDeg)}°`,label:`nacelle bearing`})},{id:`tower`,label:`Tower`,action:`tower_inside`,seconds:13,eyebrow:`Tower & access`,title:()=>`Ladder, service lift, cable loop.`,body:()=>`Power cables hang in a loop so the nacelle can yaw; converter cabinets and the transformer sit at the base.`,stat:e=>({value:t(e.lifetimeKwh/1e3),unit:`MWh`,label:`lifetime energy`})},{id:`records`,label:`Records`,action:`close_inside`,seconds:14,eyebrow:`From the open dataset`,title:e=>e.capacityFactor>0?`Lifetime capacity factor ≈ ${e.capacityFactor.toFixed(1)}%`:`Open data, CC-BY-4.0`,body:()=>`Every 10-minute SCADA interval is published on Zenodo. Grab the Parquet files from the Developers page and run your own analysis.`,stat:e=>({value:e.capacityFactor>0?e.capacityFactor.toFixed(1):`—`,unit:`%`,label:`capacity factor since commissioning`}),panel:`daily`},{id:`ask`,label:`Query`,action:`hero`,seconds:12,eyebrow:`RAG + live tools`,title:()=>`Ask Ace about the physics or the data.`,body:()=>`It answers from live telemetry, the history database and the project's documentation — and can drive this screen.`,stat:e=>({value:e.power.value,unit:e.power.unit,label:`live output`})}]}},a=Object.keys(i);export{a as n,i as t};